function hud(e){const r=cv.getBoundingClientRect(),X=e.clientX-r.left-W/2,Y=-(e.clientY-r.top-H*.52),rho=Math.hypot(X,Y),el=$('#hud');if(!rho||rho>V.R){el.textContent='';return}const c=Math.asin(rho/V.R),p0=V.la*D,la=Math.asin(Math.cos(c)*Math.sin(p0)+Y*Math.sin(c)*Math.cos(p0)/rho),lo=V.lo+Math.atan2(X*Math.sin(c),rho*Math.cos(p0)*Math.cos(c)-Y*Math.sin(p0)*Math.sin(c))/D,m=6371000/V.R;el.textContent=Math.abs(la/D).toFixed(3)+'° '+(la<0?'S':'N')+', '+lo.toFixed(3)+'° E · 1 px ≈ '+(m>=1000?(m/1000).toFixed(1)+' กม.':m.toFixed(0)+' ม.')}
