// ---- v5: live NOAA ERDDAP data (SST, chlorophyll, depth) + local moon phase -> FSI v1 per the guide ----
const EP='https://coastwatch.pfeg.noaa.gov/erddap/griddap/',SRC={sst:0,chl:0,depth:0,wx:0};
const FW={sst:1.5,chl:1.5,depth:1,moon:.5,season:.5},FT={sst:29,sw:2.5,lc:0,lw:.5,bloom:10};// STARTING weights/targets, untuned: tune from verified catch logs
const st_=k=>SRC[k]===1?'เชื่อมแล้ว':SRC[k]===-1?'เชื่อมไม่ได้':'รอข้อมูล';
async function ej(u){const r=await fetch(u);if(!r.ok)throw 0;return (await r.json()).table.rows}
function moon(d=new Date()){const syn=29.530588853,k=(d.getTime()/864e5-10962.76)/syn,ph=((k%1)+1)%1;return{ph,age:ph*syn,ill:(1-Math.cos(2*Math.PI*ph))/2}}
function moonTxt(){const m=moon(),n=m.ph<.0625||m.ph>.9375?'จันทร์ดับ':m.ph<.4375?'ข้างขึ้น '+Math.max(1,Math.round(m.age))+' ค่ำ':m.ph<.5625?'เต็มดวง':'ข้างแรม '+Math.max(1,Math.round(m.age-14.77))+' ค่ำ';return n+' · สว่าง '+Math.round(m.ill*100)+'% (โดยประมาณ)'}
function fsiOf(o){const age=t=>t?Math.max(0,(Date.now()-new Date(t))/864e5):9,fr=t=>Math.exp(-Math.max(0,age(t)-1)/3),S={sst:o.sst!=null?Math.exp(-(((o.sst-FT.sst)/FT.sw)**2)/2):0,chl:o.chl!=null?(o.chl>FT.bloom?0:Math.exp(-((Math.log10(o.chl)-FT.lc)**2)/(2*FT.lw**2))):0,depth:o.depth!=null?Math.max(0,Math.min(1,Math.min(o.depth/10,(200-o.depth)/120))):0,moon:1-o.moon.ill*.6,season:.5},A={sst:o.sst!=null?fr(o.sstT):0,chl:o.chl!=null?fr(o.chlT):0,depth:o.depth!=null?1:0,moon:1,season:1};if(o.sst==null&&o.chl==null&&o.depth==null)return null;let n=0,d=0;for(const k in FW){n+=FW[k]*A[k]*S[k];d+=FW[k]*A[k]}return 100*n/d}
function live(s){if(s.L)return s.L;const la=s.c[1],lo=s.c[0],o={moon:moon()};s.L=(async()=>{
 try{const r=await ej(EP+`jplMURSST41.json?analysed_sst[(last)][(${la})][(${lo})]`);if(r[0][3]!=null){o.sst=r[0][3];o.sstT=r[0][0]}SRC.sst=1}catch(e){if(SRC.sst!==1)SRC.sst=-1}
 try{let r;try{r=await ej(EP+`nesdisVHNchlaDaily.json?chlor_a[last-3:1:last][0:1:0][(${la})][(${lo})]`)}catch(e){r=await ej(EP+`nesdisVHNchlaDaily.json?chlor_a[last-3:1:last][(${la})][(${lo})]`)}const v=r.filter(x=>x[x.length-1]!=null).pop();if(v){o.chl=v[v.length-1];o.chlT=v[0]}SRC.chl=1}catch(e){if(SRC.chl!==1)SRC.chl=-1}
 try{const r=await ej(EP+`ETOPO_2022_v1_15s.json?z[(${la})][(${lo})]`);if(r[0][2]!=null)o.depth=Math.max(0,-r[0][2]);SRC.depth=1}catch(e){if(SRC.depth!==1)SRC.depth=-1}
 const f=fsiOf(o);if(f!=null){s.f=Math.round(f);s.live=o}return o})();return s.L}
function prefetch(){if(!st.c)return;scope().forEach(o=>live(o.s).then(()=>{if(foc&&foc.s===o.s||st.s!=null)pop()}))}
setInterval(()=>{ALL.forEach(o=>{o.s.L=null});prefetch()},18e5);
// ---- v6: horizon-clipped, densified polygons (fixes spikes/wedges at the globe limb) ----
const dense=pts=>{const o=[];for(let i=0;i<pts.length;i++){const a=pts[i],b=pts[(i+1)%pts.length],n=Math.max(1,Math.ceil(Math.max(Math.abs(b[0]-a[0]),Math.abs(b[1]-a[1]))/3));for(let j=0;j<n;j++)o.push([a[0]+(b[0]-a[0])*j/n,a[1]+(b[1]-a[1])*j/n])}return o};
LAND.forEach((l,i)=>{LAND[i]=dense(l)});TH.splice(0,TH.length,...dense(TH));
function path(pts){const p0=V.la*D,s0=Math.sin(p0),c0=Math.cos(p0),R=V.R,cx=W/2,cy=H*.52,v=pts.map(q=>{const l=(q[0]-V.lo)*D,p=q[1]*D,cl=Math.cos(p),cL=Math.cos(l);return[cl*Math.sin(l),c0*Math.sin(p)-s0*cl*cL,s0*Math.sin(p)+c0*cl*cL]}),out=[];let ex=null,fe=null;
 const lim=(a,b)=>{const t=a[2]/(a[2]-b[2]),q=[a[0]+(b[0]-a[0])*t,a[1]+(b[1]-a[1])*t],m=Math.hypot(q[0],q[1])||1;return[q[0]/m,q[1]/m,0]};
 const arc=(a1,a2)=>{let d=a2-a1;while(d>Math.PI)d-=2*Math.PI;while(d<-Math.PI)d+=2*Math.PI;const n=Math.ceil(Math.abs(d)/.1);for(let k=1;k<n;k++){const t=a1+d*k/n;out.push([Math.cos(t),Math.sin(t),0])}};
 for(let i=0;i<v.length;i++){const a=v[i],b=v[(i+1)%v.length],va=a[2]>=0,vb=b[2]>=0;if(va)out.push(a);if(va!==vb){const q=lim(a,b),ang=Math.atan2(q[1],q[0]);if(va){ex=ang;out.push(q)}else{if(ex!==null)arc(ex,ang);else fe=ang;out.push(q)}}}
 if(fe!==null&&ex!==null)arc(ex,fe);
 x.beginPath();if(out.length<3)return false;out.forEach((q,i)=>{const X=cx+R*q[0],Y=cy-R*q[1];i?x.lineTo(X,Y):x.moveTo(X,Y)});x.closePath();return true}
